// Собираем минимальные цены LED<->CEK из трёх источников.
// 1) Победа websky   — точная выдача поиска по датам окна поездки (exact).
// 2) Победа best-offers + календарь Смартавиа — витрины, цена ориентировочная.
// 3) Travelpayouts (Aviasales) — кэш ВСЕХ перевозчиков и агентств, данные до 48 ч давности.
// Смысл третьего: Победа+Смартавиа — это два сайта, а дешёвый тариф может быть у кого угодно.
// Окно поездки задаётся ОТДЕЛЬНО по направлениям: туда фиксировано, обратно (CEK->LED)
// смотрим на два дня дальше — дата возврата гибкая.
const WINDOW = {
  'LED|CEK': { min: '2026-08-30', max: '2026-09-05' },
  'CEK|LED': { min: '2026-08-30', max: '2026-09-07' },
};
const pad = n => String(n).padStart(2, '0');
const d = new Date();
const today = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;

const parseRub = s => {
  if (!s) return null;
  const digits = String(s).replace(/[^0-9]/g, '');
  return digits ? Number(digits) : null;
};
const ruToIso = s => {
  const m = String(s || '').match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
  return m ? `${m[3]}-${m[2]}-${m[1]}` : null;
};
// Неизвестное направление в окно не попадает вообще — это заодно отсекает чужие пары.
const inRange = (date, from, to) => {
  const w = WINDOW[`${from}|${to}`];
  return Boolean(w && date && date >= w.min && date <= w.max);
};
const isOurPair = (from, to) =>
  (from === 'LED' && to === 'CEK') || (from === 'CEK' && to === 'LED');

// IATA -> человеческое имя. Незнакомый код оставляем как есть.
const AIRLINES = {
  DP: 'Победа', '5N': 'Смартавиа', U6: 'Уральские', FV: 'Россия', SU: 'Аэрофлот',
  S7: 'S7', N4: 'Nordwind', WZ: 'Red Wings', A4: 'Азимут', YC: 'Ямал', UT: 'ЮТэйр',
  DN: 'Nordwind', ZF: 'Азур', EO: 'Икар', RL: 'Роял Флайт',
};

const results = [];

// --- Смартавиа: календарь, цена ориентировочная (страница поиска под антиботом) ---
const sv = [
  { node: 'Smartavia LED-CEK', key: 'LED-CEK', from: 'LED', to: 'CEK' },
  { node: 'Smartavia CEK-LED', key: 'CEK-LED', from: 'CEK', to: 'LED' },
];
for (const s of sv) {
  try {
    const data = ($(s.node).first().json.data || {})[s.key] || {};
    for (const [date, v] of Object.entries(data)) {
      if (!inRange(date, s.from, s.to)) continue;
      const p = parseRub(v && v.label && v.label.value);
      if (p) results.push({ airline: 'Смартавиа', from: s.from, to: s.to, date, price: p, direct: true, exact: false, src: 'calendar' });
    }
  } catch (e) {}
}

// --- Победа, витрина best-offers (дальний горизонт, ближние даты не отдаёт) ---
try {
  const routes = $('Pobeda').all().map(i => i.json);
  for (const r of routes) {
    if (!isOurPair(r.departure, r.arrival)) continue;
    for (const o of (r.offers || [])) {
      if (!inRange(o.depDate, r.departure, r.arrival)) continue;
      if (typeof o.price === 'number') {
        results.push({ airline: 'Победа', from: r.departure, to: r.arrival, date: o.depDate, price: o.price, direct: true, exact: false, src: 'offers' });
      }
    }
  }
} catch (e) {}

// --- Победа, websky (реальная выдача поиска по конкретной дате) ---
try {
  for (const item of $('Pobeda Websky').all()) {
    const r = item.json || {};
    const priceMap = {};
    for (const blk of (r.prices || [])) Object.assign(priceMap, blk);

    for (const chain of (r.flights || [])) {
      const segs = chain.flights || [];
      if (!segs.length) continue;
      const from = segs[0].origincity;
      const to = segs[segs.length - 1].destinationcity;
      if (!isOurPair(from, to)) continue;

      const date = ruToIso(segs[0].departuredate);
      if (!inRange(date, from, to)) continue;

      const prices = (priceMap[chain.chainId] || [])
        .map(p => Number(p.price))
        .filter(n => Number.isFinite(n) && n > 0);
      if (!prices.length) continue;

      results.push({ airline: 'Победа', from, to, date, price: Math.min(...prices), direct: segs.length === 1, exact: true, src: 'websky' });
    }
  }
} catch (e) {}

// --- Travelpayouts / Aviasales: все перевозчики и агентства, кэш до 48 ч ---
// Схему полей не проверяли живьём (доки закрыты), поэтому читаем и v3, и v2-варианты имён.
try {
  for (const item of $('Travelpayouts').all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const rows = Array.isArray(r.data) ? r.data : (Array.isArray(r) ? r : []);

    for (const t of rows) {
      const date = String(t.departure_at || t.depart_date || '').slice(0, 10);

      const from = t.origin;
      const to = t.destination;
      if (!isOurPair(from, to)) continue;
      if (!inRange(date, from, to)) continue;

      const price = Number(t.price != null ? t.price : t.value);
      if (!Number.isFinite(price) || price <= 0) continue;

      const stops = Number(t.transfers != null ? t.transfers : t.number_of_changes);
      const code = t.airline;

      results.push({
        airline: AIRLINES[code] || code || 'н/д',
        from, to, date, price,
        direct: Number.isFinite(stops) ? stops === 0 : null,
        exact: false, src: 'aviasales',
      });
    }
  }
} catch (e) {}

// websky — живой поиск Победы, и он авторитетен ПО ПОБЕДЕ на те даты, что мы реально спрашивали.
// Проверено 2026-07-20: витрина best-offers показывала CEK->LED на сегодня за 19598 ₽,
// а поиск на эту дату отвечает "рейсов нет". Поэтому витрину/кэш по Победе на спрошенных датах
// выкидываем целиком — иначе бот зовёт на несуществующий рейс.
// Про других перевозчиков websky не знает ничего, их записи не трогаем.
// Важно: с 2026-08 websky иногда отдаёт 403 (анти-бот). Нода настроена на retry +
// continueRegularOutput, поэтому упавшая дата приходит item'ом с json.error. Такую дату
// НЕЛЬЗЯ считать спрошенной — иначе мы выкинем витринную цену Победы, ничего не получив взамен.
const queried = new Set();
try {
  const asked = $('Websky Dates').all();
  const answers = $('Pobeda Websky').all();
  const sameShape = answers.length === asked.length;
  asked.forEach((q, i) => {
    const a = sameShape ? answers[i] : null;
    if (sameShape && (!a || (a.json && a.json.error && !a.json.result))) return; // 403/сбой — дату не считаем
    const iso = ruToIso(q.json.date_ru);
    if (iso) queried.add(`${q.json.from}|${q.json.to}|${iso}`);
  });
} catch (e) {}

const merged = results.filter(r => {
  if (r.exact) return true;
  if (r.airline === 'Победа' && queried.has(`${r.from}|${r.to}|${r.date}`)) return false;
  return true;
});

const isToday = r => r.date === today;
const pickMin = (from, to, extra) => {
  const f = merged
    .filter(r => r.from === from && r.to === to && (!extra || extra(r)))
    .sort((a, b) => a.price - b.price);
  return f[0] || null;
};

return [{ json: {
  today,
  // минимум по всему окну направления (LED->CEK по 05.09, CEK->LED по 07.09)
  ledcek: pickMin('LED', 'CEK'),
  cekled: pickMin('CEK', 'LED'),
  // отдельно — вылет СЕГОДНЯ (last-minute, свой порог в Prepare)
  ledcek_today: pickMin('LED', 'CEK', isToday),
  cekled_today: pickMin('CEK', 'LED', isToday),
  count: merged.length,
  bySource: merged.reduce((acc, r) => { acc[r.src] = (acc[r.src] || 0) + 1; return acc; }, {}),
} }];

// ===================== НАСТРОЙКИ =====================
const THRESHOLD = 8000;         // 🔥 жёсткий порог по всему окну дат
const TODAY_THRESHOLD = 12000;  // ⏰ порог для вылета СЕГОДНЯ (last-minute сброс)
const DROP_PCT = 10;            // 📉 мягкий алерт: падение от прошлого минимума, %
const CHAT_ID = '648226895';
// =====================================================

const agg = $('Aggregate').first().json;
const store = $getWorkflowStaticData('global'); // переживает запуски, без внешней БД
const today = agg.today;

const NOTE = {
  websky: '',
  aviasales: '\n⚠️ Цена из кэша Aviasales — проверь на сайте перевозчика.',
  offers: '\n⚠️ Цена с витрины Победы, ориентировочная.',
  calendar: '\n⚠️ Цена из календаря Смартавиа, ориентировочная.',
};

const out = [];
const push = text => out.push({ json: { chat_id: CHAT_ID, text } });
const describe = m =>
  `${m.airline} · ${m.date} — ${m.price} ₽${m.direct === false ? ' · с пересадкой' : ''}`;

const dirs = [
  { route: 'LED-CEK', label: 'СПб → Челябинск', cur: agg.ledcek, curToday: agg.ledcek_today },
  { route: 'CEK-LED', label: 'Челябинск → СПб', cur: agg.cekled, curToday: agg.cekled_today },
];

for (const dir of dirs) {
  // ---------- минимум по всему окну ----------
  if (dir.cur) {
    const price = dir.cur.price;
    const last = (store[dir.route] == null) ? null : Number(store[dir.route]);
    const note = NOTE[dir.cur.src] || '';
    const was = (last == null) ? '' : ` (было ${last} ₽)`;

    if (price <= THRESHOLD && (last == null || price < last)) {
      push(`🔥 ${dir.label}\n${describe(dir.cur)}${was}\nБери, пока не разобрали!${note}`);
    } else if (last != null && price <= last * (1 - DROP_PCT / 100)) {
      // цена всё ещё выше порога, но заметно упала — раньше такое бот пропускал молча
      push(`📉 ${dir.label}: цена упала\n${describe(dir.cur)}${was}${note}`);
    }
    store[dir.route] = price;
  }

  // ---------- отдельно: вылет СЕГОДНЯ ----------
  // Свой порог и свой счётчик минимума, который обнуляется с началом новых суток.
  if (dir.curToday) {
    const key = `${dir.route}:today`;
    const prev = store[key];
    const lastToday = (prev && prev.date === today) ? Number(prev.price) : null;
    const price = dir.curToday.price;

    if (price <= TODAY_THRESHOLD && (lastToday == null || price < lastToday)) {
      const was = (lastToday == null) ? '' : ` (было ${lastToday} ₽)`;
      push(`⏰ Вылет СЕГОДНЯ: ${dir.label}\n${describe(dir.curToday)}${was}\n` +
           `Последний шанс!${NOTE[dir.curToday.src] || ''}`);
    }
    store[key] = { date: today, price };
  }
}

// чистим хвосты за прошлые дни, чтобы staticData не пух
for (const k of Object.keys(store)) {
  if (k.endsWith(':today') && store[k] && store[k].date !== today) delete store[k];
}

return out; // 0..4 сообщения -> прямо в Telegram

