    }
  }
} catch (e) {}

// --- Travelpayouts / Aviasales: все перевозчики и агентства, кэш до 48 ч ---
// Схему полей не проверяли живьём (доки закрыты), поэтому читаем и v3, и v2-варианты имён.
try {
  for (const item of $('Travelpayouts Cmd').all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const rows = Array.isArray(r.data) ? r.data : (Array.isArray(r) ? r : []);

    for (const t of rows) {
      const date = String(t.departure_at || t.depart_date || '').slice(0, 10);

      const from = t.origin;
      const to = t.destination;
      if (!isOurPair(from, to)) continue;
