        airline: AIRLINES[code] || code || 'н/д',
        from, to, date, price,
        direct: Number.isFinite(stops) ? stops === 0 : null,
        exact: false, src: 'aviasales',
      });
    }
  }
} catch (e) {}

// websky — живой поиск Победы, и он авторитетен ПО ПОБЕДЕ на те даты, что мы реально спрашивали.
// Проверено 2026-07-20: витрина best-offers показывала CEK->LED на сегодня за 19598 ₽,
// а поиск на эту дату отвечает "рейсов нет". Поэтому витрину/кэш по Победе на спрошенных датах
// выкидываем целиком — иначе бот зовёт на несуществующий рейс.
// Про других перевозчиков websky не знает ничего, их записи не трогаем.
// См. комментарий в Aggregate: упавшую по 403 дату не считаем спрошенной.
const queried = new Set();
try {
  const asked = $('Websky Dates Cmd').all();
  const answers = $('Pobeda Websky Cmd').all();
  const sameShape = answers.length === asked.length;
  asked.forEach((q, i) => {
    const a = sameShape ? answers[i] : null;
    if (sameShape && (!a || (a.json && a.json.error && !a.json.result))) return;
    const iso = ruToIso(q.json.date_ru);
    if (iso) queried.add(`${q.json.from}|${q.json.to}|${iso}`);
  });
} catch (e) {}

const merged = results.filter(r => {
  if (r.exact) return true;
  if (r.airline === 'Победа' && queried.has(`${r.from}|${r.to}|${r.date}`)) return false;
  return true;
});

const isToday = r => r.date === today;
const pick = (from, to) => {
  const f = merged.filter(r => r.from === from && r.to === to).sort((a, b) => a.price - b.price);
  const byAir = {};
  for (const r of f) { if (!byAir[r.airline]) byAir[r.airline] = r; }
  const top = Object.values(byAir).sort((a, b) => a.price - b.price).slice(0, 5);
  const todayList = f.filter(isToday);
  return { best: f[0] || null, top, today: todayList[0] || null };
};

return [{ json: { today, LEDCEK: pick('LED', 'CEK'), CEKLED: pick('CEK', 'LED'), count: merged.length } }];

// Форматируем ответ на команду /prices.
const a = $('Aggregate Cmd').first().json;
const chat_id = $('On Command').first().json.message.chat.id;

// 2026-08-30 -> 30.08
const dm = d => { const p = String(d).split('-'); return p.length === 3 ? `${p[2]}.${p[1]}` : d; };

// Откуда цена. Живой поиск не помечаем никак — это норма, помечаем только неточное.
const SRC = {
  websky: '',
  offers: ' · примерно',
  calendar: ' · примерно',
  aviasales: ' · примерно (Aviasales)',
};
const marks = m => `${m.direct === false ? ' · с пересадкой' : ''}${SRC[m.src] || ''}`;
const fmt = m => m ? `${m.price} ₽ · ${m.airline} · ${dm(m.date)}${marks(m)}` : 'нет мест';

function block(title, pick) {
  let s = `${title}\nДешевле всего: ${fmt(pick.best)}\n`;
  for (const m of (pick.top || [])) {
    s += `  • ${m.airline}: ${m.price} ₽ (${dm(m.date)})${marks(m)}\n`;
  }
  return s;
}

const text =
  `✈️ Цены LED↔CEK (30 авг – 5 сен)\n\n` +
  block('СПб → Челябинск', a.LEDCEK) + `\n` +
  block('Челябинск → СПб', a.CEKLED) +
  `\nВсего вариантов: ${a.count}\n\n` +
  `«примерно» — цена из календаря или витрины перевозчика, на сайте может отличаться.\n` +
  `Без пометки — цена из живого поиска, ей можно верить.`;

return [{ json: { chat_id, text } }];

// Формируем уведомление о падении воркфлоу.
// Крон раз в 5 мин: если внешний API лежит часами, без троттлинга прилетают десятки
// одинаковых сообщений (05.08 их пришло 40 подряд). Поэтому по каждой ноде шлём
// не чаще раза в 30 мин, а сколько раз подавили — дописываем в следующее сообщение.
const QUIET_MS = 30 * 60 * 1000;

const e = $json.execution || {};
const err = e.error || {};
const wf = $json.workflow || {};
const node = e.lastNodeExecuted || '?';

const s = $getWorkflowStaticData('global');
if (!s.errAlerts) s.errAlerts = {};
const st = s.errAlerts[node] || { last: 0, suppressed: 0 };
const now = Date.now();

if (now - st.last < QUIET_MS) {
  st.suppressed += 1;
  s.errAlerts[node] = st;
  return [];
}

const repeats = st.suppressed;
s.errAlerts[node] = { last: now, suppressed: 0 };

const text =
  `⚠️ FlightWatch упал\n` +
  `Воркфлоу: ${wf.name || '?'}\n` +
  `Нода: ${node}\n` +
  `Ошибка: ${err.message || 'без текста'}` +
  (repeats ? `\n(за последние 30 мин ещё ${repeats} таких, они скрыты)` : '') +
  (e.url ? `\n${e.url}` : '');

return [{ json: { chat_id: '648226895', text } }];

// Точный поиск Победы по всем датам окна поездки, оба направления.
// Окно фиксированное — поездка 30.08–05.09.2026, обратно смотрим до 07.09 (гибкий возврат).
const WINDOW = {
  'LED|CEK': { min: '2026-08-30', max: '2026-09-05' },
  'CEK|LED': { min: '2026-08-30', max: '2026-09-07' },
};

const days = (min, max) => {
  const out = [];
  const cur = new Date(`${min}T00:00:00Z`);
  const end = new Date(`${max}T00:00:00Z`);
  while (cur <= end && out.length < 60) {
    out.push(cur.toISOString().slice(0, 10));
    cur.setUTCDate(cur.getUTCDate() + 1);
  }
  return out;
};

const out = [];
for (const [pair, w] of Object.entries(WINDOW)) {
  const [from, to] = pair.split('|');
  for (const iso of days(w.min, w.max)) {
    const [y, m, dd] = iso.split('-');
    out.push({ json: { date_ru: `${dd}.${m}.${y}`, from, to } });
  }
}
return out;

