// Запросы в Travelpayouts: оба направления × месяцы окна поездки.
// departure_at принимает YYYY-MM, поэтому режем окно помесячно; лишние даты
// внутри месяца отсекает inRange в Aggregate.
const MIN_DATE = '2026-08-30';
const MAX_DATE = '2026-09-07'; // самая дальняя граница по направлениям
const pad = n => String(n).padStart(2, '0');

const cur = new Date(Number(MIN_DATE.slice(0, 4)), Number(MIN_DATE.slice(5, 7)) - 1, 1);
const end = new Date(Number(MAX_DATE.slice(0, 4)), Number(MAX_DATE.slice(5, 7)) - 1, 1);

const months = [];
while (cur <= end && months.length < 24) {
  months.push(`${cur.getFullYear()}-${pad(cur.getMonth() + 1)}`);
  cur.setMonth(cur.getMonth() + 1);
}

const out = [];
for (const month of months) {
  out.push({ json: { origin: 'LED', destination: 'CEK', month } });
  out.push({ json: { origin: 'CEK', destination: 'LED', month } });
}
return out;

